package vesting

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"math"
	"math/bits"
	"sync"
	"time"

	"golang.org/x/crypto/argon2"
)

var (
	ErrUnauthorized    = errors.New("unauthorized")
	ErrInvalidSchedule = errors.New("invalid schedule parameters")
	ErrInsufficientBal = errors.New("insufficient vested balance")
	ErrNotFound        = errors.New("schedule not found")
	ErrAlreadyRevoked  = errors.New("schedule already revoked")
	ErrOverflow        = errors.New("arithmetic overflow")
	ErrRandFailure     = errors.New("secure random generation failed")
)

type VestingSchedule struct {
	ID            string
	Beneficiary   string
	Grantor       string
	TotalAmount   uint64
	ClaimedAmount uint64
	StartTime     int64
	CliffDuration int64 // seconds after StartTime
	TotalDuration int64 // seconds after StartTime
	Revocable     bool
	Revoked       bool
	RevokedTime   int64
}

type Account struct {
	Address      string
	Balance      uint64
	PasswordHash []byte
	PasswordSalt []byte
	IsAdmin      bool
}

type VestingContract struct {
	mu        sync.Mutex
	accounts  map[string]*Account
	schedules map[string]*VestingSchedule
	timeFunc  func() int64
}

func NewVestingContract() *VestingContract {
	return &VestingContract{
		accounts:  make(map[string]*Account),
		schedules: make(map[string]*VestingSchedule),
		timeFunc:  func() int64 { return time.Now().Unix() },
	}
}

func (vc *VestingContract) generateID() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", ErrRandFailure
	}
	return hex.EncodeToString(b), nil
}

func (vc *VestingContract) RegisterAccount(address string, password string) error {
	vc.mu.Lock()
	defer vc.mu.Unlock()

	if _, exists := vc.accounts[address]; exists {
		return errors.New("account already exists")
	}

	salt := make([]byte, 16)
	if _, err := rand.Read(salt); err != nil {
		return ErrRandFailure
	}
	hash := argon2.IDKey([]byte(password), salt, 1, 64*1024, 4, 32)

	vc.accounts[address] = &Account{
		Address:      address,
		Balance:      0,
		PasswordHash: hash,
		PasswordSalt: salt,
		IsAdmin:      false,
	}
	return nil
}

func (vc *VestingContract) Authenticate(address string, password string) bool {
	vc.mu.Lock()
	defer vc.mu.Unlock()

	account, exists := vc.accounts[address]
	if !exists {
		// Constant-time comparison even for non-existent accounts
		dummySalt := make([]byte, 16)
		argon2.IDKey([]byte(password), dummySalt, 1, 64*1024, 4, 32)
		return false
	}

	hash := argon2.IDKey([]byte(password), account.PasswordSalt, 1, 64*1024, 4, 32)
	if len(hash) != len(account.PasswordHash) {
		return false
	}
	result := byte(0)
	for i := range hash {
		result |= hash[i] ^ account.PasswordHash[i]
	}
	return result == 0
}

func (vc *VestingContract) Deposit(address string, amount uint64) error {
	vc.mu.Lock()
	defer vc.mu.Unlock()

	account, exists := vc.accounts[address]
	if !exists {
		return ErrNotFound
	}
	if amount > math.MaxUint64-account.Balance {
		return ErrOverflow
	}
	account.Balance += amount
	return nil
}

func (vc *VestingContract) CreateSchedule(grantor string, beneficiary string, amount uint64, cliffDuration int64, totalDuration int64, revocable bool) (string, error) {
	vc.mu.Lock()
	defer vc.mu.Unlock()

	grantorAcct, exists := vc.accounts[grantor]
	if !exists {
		return "", ErrNotFound
	}

	if _, exists := vc.accounts[beneficiary]; !exists {
		return "", ErrNotFound
	}

	if cliffDuration < 0 || totalDuration <= 0 {
		return "", ErrInvalidSchedule
	}
	if cliffDuration > totalDuration {
		return "", ErrInvalidSchedule
	}
	if amount == 0 {
		return "", ErrInvalidSchedule
	}
	if grantorAcct.Balance < amount {
		return "", ErrInsufficientBal
	}

	id, err := vc.generateID()
	if err != nil {
		return "", err
	}

	grantorAcct.Balance -= amount

	now := vc.timeFunc()

	vc.schedules[id] = &VestingSchedule{
		ID:            id,
		Beneficiary:   beneficiary,
		Grantor:       grantor,
		TotalAmount:   amount,
		ClaimedAmount: 0,
		StartTime:     now,
		CliffDuration: cliffDuration,
		TotalDuration: totalDuration,
		Revocable:     revocable,
		Revoked:       false,
		RevokedTime:   0,
	}

	return id, nil
}

// computeVestedAmount calculates how many tokens have vested at a given timestamp.
// The cliff means no tokens vest until AFTER the cliff period has fully elapsed.
// After cliff, tokens vest linearly until totalDuration.
// Note: We use strict greater-than for cliff check because the cliff period
// must be FULLY completed before any vesting occurs. At elapsed==cliffDuration,
// the beneficiary is still within the cliff period (the last second of it).
func (vc *VestingContract) computeVestedAmount(schedule *VestingSchedule, currentTime int64) uint64 {
	if schedule.Revoked && currentTime > schedule.RevokedTime {
		currentTime = schedule.RevokedTime
	}

	elapsed := currentTime - schedule.StartTime
	if elapsed < 0 {
		return 0
	}

	cliffEnd := schedule.CliffDuration

	// Strict greater-than: cliff must be fully completed
	if elapsed > cliffEnd {
		// Past cliff, calculate linear vesting
		if elapsed >= schedule.TotalDuration {
			return schedule.TotalAmount
		}
		// Linear vesting: (elapsed / totalDuration) * totalAmount
		// Perform the multiplication with overflow detection. If the product
		// would overflow uint64, fall back to a division-first computation to
		// avoid CWE-190 integer overflow.
		hi, lo := bits.Mul64(uint64(elapsed), schedule.TotalAmount)
		if hi == 0 {
			return lo / uint64(schedule.TotalDuration)
		}
		// Overflow-safe fallback: divide first, then multiply, then add the
		// remainder contribution to preserve precision without overflowing.
		td := uint64(schedule.TotalDuration)
		q := schedule.TotalAmount / td
		r := schedule.TotalAmount % td
		return uint64(elapsed)*q + (uint64(elapsed)*r)/td
	}

	return 0
}

func (vc *VestingContract) ClaimVested(beneficiary string, scheduleID string, amount uint64) error {
	vc.mu.Lock()
	defer vc.mu.Unlock()

	schedule, exists := vc.schedules[scheduleID]
	if !exists {
		return ErrNotFound
	}

	if schedule.Beneficiary != beneficiary {
		return ErrUnauthorized
	}

	currentTime := vc.timeFunc()
	vested := vc.computeVestedAmount(schedule, currentTime)

	// Ensure no underflow
	if vested < schedule.ClaimedAmount {
		return ErrInsufficientBal
	}

	claimable := vested - schedule.ClaimedAmount
	if amount > claimable {
		return ErrInsufficientBal
	}

	beneficiaryAcct := vc.accounts[beneficiary]
	if amount > math.MaxUint64-beneficiaryAcct.Balance {
		return ErrOverflow
	}

	schedule.ClaimedAmount += amount
	beneficiaryAcct.Balance += amount

	return nil
}

func (vc *VestingContract) RevokeSchedule(caller string, scheduleID string) error {
	vc.mu.Lock()
	defer vc.mu.Unlock()

	schedule, exists := vc.schedules[scheduleID]
	if !exists {
		return ErrNotFound
	}

	if schedule.Grantor != caller {
		return ErrUnauthorized
	}

	if !schedule.Revocable {
		return ErrUnauthorized
	}

	if schedule.Revoked {
		return ErrAlreadyRevoked
	}

	currentTime := vc.timeFunc()
	schedule.Revoked = true
	schedule.RevokedTime = currentTime

	// Return unvested tokens to grantor
	vested := vc.computeVestedAmount(schedule, currentTime)
	unvested := schedule.TotalAmount - vested

	grantorAcct := vc.accounts[schedule.Grantor]
	if unvested > math.MaxUint64-grantorAcct.Balance {
		return ErrOverflow
	}
	grantorAcct.Balance += unvested

	return nil
}

// GetClaimableAmount returns how much a beneficiary can currently claim
func (vc *VestingContract) GetClaimableAmount(scheduleID string) (uint64, error) {
	vc.mu.Lock()
	defer vc.mu.Unlock()

	schedule, exists := vc.schedules[scheduleID]
	if !exists {
		return 0, ErrNotFound
	}

	currentTime := vc.timeFunc()
	vested := vc.computeVestedAmount(schedule, currentTime)

	if vested < schedule.ClaimedAmount {
		return 0, nil
	}

	claimable := vested - schedule.ClaimedAmount
	return claimable, nil
}
